from pathlib import Path
import base64
import gzip

ROOT = Path(__file__).resolve().parents[2]
LEDGER = ROOT / "docs/running-example-ledger.md"
VERIFIER = ROOT / "scripts/verify-running-example.mjs"
README = ROOT / "README.md"
PAGES = ROOT / ".github/workflows/pages.yml"
STORIES = ROOT / "docs/stories.md"

LEDGER_B64 = """"""
VERIFIER_B64 = """"""


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise SystemExit(f"{label}: expected one replacement target, found {count}")
    return text.replace(old, new, 1)


if LEDGER.exists() or VERIFIER.exists():
    raise SystemExit("COH-3.1 target files already exist; refusing to overwrite them.")

LEDGER.write_bytes(gzip.decompress(base64.b64decode(LEDGER_B64)))
VERIFIER.write_bytes(gzip.decompress(base64.b64decode(VERIFIER_B64)))

readme = README.read_text(encoding="utf-8")
readme = replace_once(
    readme,
    "- `docs/` — visual-development plans, character bibles, storyboard source documents, and the implementation backlog",
    "- `docs/` — the canonical running-example ledger, visual-development plans, character bibles, storyboard source documents, and the implementation backlog",
    "README repository-layout description",
)

old_validation = """## Validate book structure

Run the consistency check from the repository root:

```bash
node scripts/check-book-consistency.mjs
```

The check evaluates `site/book-data.js` without a browser and verifies ordered, contiguous and unique parts and chapters; one-part-only chapter membership; source-file existence; previous/next lookup behaviour; and the required desktop/mobile part-navigation integration. It exits with a numbered error list when metadata or navigation wiring is inconsistent.

The GitHub Pages workflow runs the same command before assembling the published site, so invalid part metadata or broken progress-navigation integration blocks deployment.
"""
new_validation = """## Validate book structure and the running example

Run both checks from the repository root:

```bash
node scripts/check-book-consistency.mjs
node scripts/verify-running-example.mjs
```

The structure check evaluates `site/book-data.js` without a browser and verifies ordered, contiguous and unique parts and chapters; one-part-only chapter membership; source-file existence; previous/next lookup behaviour; and the required desktop/mobile part-navigation integration.

The running-example check reads [`docs/running-example-ledger.md`](docs/running-example-ledger.md), independently recomputes the `THE CAT SAT` path from projections through vocabulary probabilities, checks shapes and documented tolerances, and confirms that each canonical value is traceable to its owning chapter section.

The GitHub Pages workflow runs both commands before assembling the published site, so broken navigation metadata or numerical drift blocks deployment.
"""
readme = replace_once(readme, old_validation, new_validation, "README validation section")
README.write_text(readme, encoding="utf-8")

pages = PAGES.read_text(encoding="utf-8")
pages = replace_once(
    pages,
    "      - 'scripts/**'\n      - '.github/workflows/pages.yml'",
    "      - 'scripts/**'\n      - 'docs/running-example-ledger.md'\n      - '.github/workflows/pages.yml'",
    "Pages workflow trigger paths",
)
pages = replace_once(
    pages,
    "      - name: Validate book structure and navigation\n        run: node scripts/check-book-consistency.mjs\n\n      - name: Configure GitHub Pages",
    "      - name: Validate book structure and navigation\n        run: node scripts/check-book-consistency.mjs\n\n      - name: Verify canonical running example\n        run: node scripts/verify-running-example.mjs\n\n      - name: Configure GitHub Pages",
    "Pages running-example validation step",
)
PAGES.write_text(pages, encoding="utf-8")

stories = STORIES.read_text(encoding="utf-8")
stories = replace_once(
    stories,
    "## COH-3.1 — Create the canonical running-example ledger\n\n**Status:** Planned",
    "## COH-3.1 — Create the canonical running-example ledger\n\n**Status:** Complete",
    "COH-3.1 story status",
)
STORIES.write_text(stories, encoding="utf-8")

print("COH-3.1 ledger, verifier, documentation, workflow, and story status generated.")
